(()=>{
 'use strict';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fa=n=>Number(n).toLocaleString('fa-IR',{maximumFractionDigits:4});
 const input=(name,label,value='',type='text',extra='')=>'<label class="form-control"><span>'+label+'</span><input class="input" name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>';
 const checks=(confirmation)=>input('reason','دلیل تغییر','','text','required minlength="5" maxlength="500"')+input('confirmation','برای تأیید بنویس: '+esc(confirmation),'','text','required autocomplete="off"')+'<button class="btn btn-primary" type="submit">'+window.RI.icon('check')+'ثبت تغییر</button><p role="status"></p>';
 window.ownerUserControls=(d)=>{
  const u=d.user,confirmation=u.phone||u.id,active=d.access.filter(x=>x.ref.startsWith('subscription:')&&Number(x.expires_at)>Date.now()).sort((a,b)=>Number(b.expires_at)-Number(a.expires_at))[0];
  const form=(id,body)=>'<form class="owner-control-form" data-owner-operation="'+id+'" data-user="'+u.id+'" '+(id!=='subscription'?'hidden':'')+'>'+body+checks(confirmation)+'</form>';
  return '<section class="owner-workspace"><h2>'+window.RI.icon('shield')+'کنترل پیشرفتهٔ مالک</h2><p>دسترسی حساس به همین حساب؛ هر تغییر با دلیل و تأیید دقیق ثبت می‌شود.</p><div class="tabs" role="tablist" aria-label="کنترل پیشرفته مالک">'+[['subscription','اشتراک و زمان'],['password','امنیت و رمز'],['profile','مشخصات کامل'],['access','دسترسی محصولات'],['wallet','اصلاح اعتبار'],['extra-subdomain','سهمیهٔ صفحه']].map(([id,label])=>'<button type="button" class="tab" role="tab" data-owner-tab="'+id+'" aria-selected="'+(id==='subscription')+'">'+label+'</button>').join('')+'</div>'+
  form('subscription','<p>این تغییر، اشتراک فعال قبلی را جایگزین می‌کند؛ پرداخت بانکی یا خرید جعلی ثبت نمی‌شود.</p><label>نوع اشتراک<select class="select" name="plan">'+[['none','بدون اشتراک'],['q','رخش · سه‌ماهه'],['h','سیمرغ · شش‌ماهه'],['y','هما · سالانه']].map(([id,label])=>'<option value="'+id+'" '+((active?.ref.split(':')[1]||'none')===id?'selected':'')+'>'+label+'</option>').join('')+'</select></label>'+input('days','روزهای باقی‌مانده از امروز',active?Math.max(1,Math.ceil((active.expires_at-Date.now())/86400000)):90,'number','required min="0" max="3650" step="1"'))+
  form('password','<p class="notice">رمز قبلی قابل نمایش نیست. تعیین رمز تازه تمام نشست‌های کاربر و کدهای بازیابی فعلی را باطل می‌کند.</p>'+input('password','رمز تازه (حداقل ۱۲ کاراکتر، حروف بزرگ و کوچک انگلیسی و عدد)','','password','required minlength="12" maxlength="128" autocomplete="new-password"')+'<label class="check"><input class="checkbox" type="checkbox" name="show-password">نمایش رمز تازه</label>')+
  form('profile',input('first_name','نام',u.first_name,'text','required maxlength="39"')+input('last_name','نام خانوادگی',u.last_name,'text','required maxlength="39"')+input('role','عنوان حرفه‌ای',u.role,'text','maxlength="100"')+'<label>معرفی<textarea class="textarea" name="bio" maxlength="500">'+esc(u.bio)+'</textarea></label><p>شمارهٔ تأییدشده از این فرم تغییر نمی‌کند؛ انتقال شماره به تأیید هویت واقعی نیاز دارد.</p>')+
  form('access','<label>محصول<select class="select" name="ref" data-owner-products><option value="rt:vista">قالب ویستا</option></select></label><label>دسترسی<select class="select" name="enabled"><option value="true">اعطای دائمی</option><option value="false">لغو دسترسی خریداری‌شده</option></select></label><p>اشتراک ممکن است همچنان دسترسی به محصول را بدهد. این عملیات سابقهٔ پرداخت را تغییر نمی‌دهد.</p>')+
  form('wallet','<p>موجودی ثبت‌شده: '+fa(Number(d.balance_units)/2000)+' It. اصلاح اعتبار یک تراکنش مستقل ثبت می‌کند؛ سابقهٔ بانکی دست‌کاری نمی‌شود و موجودی منفی مجاز نیست.</p>'+input('delta','مقدار تغییر به It؛ مثبت برای افزایش و منفی برای کسر',0,'number','required min="-50000" max="50000" step="0.0005"'))+
  form('extra-subdomain','<label class="admin-channel-row"><span><b>یک ریزدامنهٔ اضافه</b><small>رایگان: ۲ ریزدامنه · اشتراکی: ۳ ریزدامنه. آدرس مسیری اشتراکی جدا باقی می‌ماند.</small></span><input class="toggle" type="checkbox" name="enabled" '+(d.ownerSettings?.extraSubdomain?'checked':'')+'></label><p>لغو سهمیه محتوای قبلی را حذف نمی‌کند؛ ویرایش و نمایش عمومی جایگاه اضافه متوقف می‌شود.</p>')+'</section>';
 };
 window.ownerCommerceControls=d=>'<section class="owner-workspace"><h2>'+window.RI.icon('settings')+'قیمت‌گذاری و محدودیت‌ها</h2><p>تعداد It قبلی کاربران ثابت می‌ماند؛ نرخ تازه فقط روی شارژهای جدید اعمال می‌شود. پیش‌فاکتورهای قبلی نرخ خودشان را حفظ می‌کنند.</p><form id="owner-commerce-form">'+input('rate','تومان برای هر It جدید',d.policy.rate,'number','required min="100" max="10000000" step="1"')+input('imagePaid','سقف عکس اشتراکی، کیلوبایت',d.policy.imagePaid/1024,'number','required min="5" max="2048" step="1"')+input('imageFree','سقف عکس رایگان، کیلوبایت (حداکثر یک‌پنجم)',d.policy.imageFree/1024,'number','required min="1" max="409" step="1"')+'<label>جست‌وجوی محصول<input class="input" data-owner-product-search type="search" placeholder="نام یا شناسهٔ محصول"></label><div class="owner-product-list">'+Object.entries({rt:d.templates,lt:d.linkTemplates,font:d.fonts,pal:d.palettes,subscription:Object.values(d.plans)}).flatMap(([kind,list])=>list.map(x=>'<div class="owner-product-row" data-owner-product="'+kind+':'+x.id+'"><label><b>'+esc(x.name)+'</b><small dir="ltr">'+kind+':'+x.id+'</small></label>'+(x.price?'<label>قیمت It<input class="input" type="number" data-owner-price min="1" max="50000" step="1" value="'+x.price/2000+'" required></label>':'<span>رایگان</span>')+'<label class="check"><input class="checkbox" type="checkbox" data-owner-paused '+(x.paused?'checked':'')+'>توقف فروش</label></div>')).join('')+'</div>'+checks('تغییر تنظیمات فروش')+'</form></section>';
 window.bindOwnerControls=(api,reload,ownerId)=>{
  document.addEventListener('keydown',e=>{const tab=e.target.closest('[data-owner-tab]');if(!tab||!['Home','End','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const tabs=[...tab.parentElement.querySelectorAll('[data-owner-tab]')],index=tabs.indexOf(tab),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowLeft'?1:-1)+tabs.length)%tabs.length;tabs[next].click();tabs[next].focus();});
  document.addEventListener('click',e=>{const tab=e.target.closest('[data-owner-tab]');if(!tab)return;const root=tab.closest('.owner-workspace');root.querySelectorAll('[data-owner-tab]').forEach(b=>b.setAttribute('aria-selected',String(b===tab)));root.querySelectorAll('[data-owner-operation]').forEach(f=>f.hidden=f.dataset.ownerOperation!==tab.dataset.ownerTab);if(tab.dataset.ownerTab==='access'){const select=root.querySelector('[data-owner-products]');if(!select.dataset.ready)api('catalog').then(d=>{if(!select.isConnected)return;select.innerHTML=Object.entries({rt:d.templates,lt:d.linkTemplates,font:d.fonts,pal:d.palettes}).flatMap(([kind,list])=>list.map(x=>'<option value="'+kind+':'+x.id+'">'+esc(x.name)+' · '+kind+'</option>')).join('');select.dataset.ready='true';}).catch(error=>{select.closest('form').querySelector('[role=status]').textContent=error.message;});}});
  document.addEventListener('input',e=>{if(!e.target.matches('[data-owner-product-search]'))return;const q=e.target.value.trim().toLowerCase();e.target.closest('form').querySelectorAll('[data-owner-product]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q)&&!row.dataset.ownerProduct.includes(q));});
  document.addEventListener('change',e=>{if(e.target.name==='show-password')e.target.closest('form').elements.password.type=e.target.checked?'text':'password';});
  document.addEventListener('submit',async e=>{
   const form=e.target;if(!form.matches('[data-owner-operation],#owner-commerce-form'))return;e.preventDefault();if(form.dataset.pending)return;form.dataset.pending='true';const button=form.querySelector('[type=submit]'),status=form.querySelector('[role=status]');button.disabled=true;status.textContent='در حال ثبت…';const fields=Object.fromEntries(new FormData(form)),requestId=form.dataset.requestId||(form.dataset.requestId=crypto.randomUUID());
   try{if(form.id==='owner-commerce-form'){const settings={rate:Number(fields.rate),imageFree:Number(fields.imageFree)*1024,imagePaid:Number(fields.imagePaid)*1024,prices:{},paused:[]};form.querySelectorAll('[data-owner-product]').forEach(row=>{const price=row.querySelector('[data-owner-price]');if(price)settings.prices[row.dataset.ownerProduct]=Number(price.value)*2000;if(row.querySelector('[data-owner-paused]').checked)settings.paused.push(row.dataset.ownerProduct);});await api('commerce',{settings,reason:fields.reason,confirmation:fields.confirmation,requestId});}
   else {const operation=form.dataset.ownerOperation,data={...fields};delete data.reason;delete data.confirmation;delete data['show-password'];if(operation==='subscription')data.days=Number(data.days);if(operation==='wallet')data.delta=Number(data.delta);if(operation==='access')data.enabled=fields.enabled==='true';if(operation==='extra-subdomain')data.enabled=!!form.elements.enabled.checked;await api('users/'+form.dataset.user+'/owner-controls',{operation,data,reason:fields.reason,confirmation:fields.confirmation,requestId});if(operation==='password'&&form.dataset.user===ownerId()){location.assign('/login/');return;}}
   status.textContent='تغییر ذخیره و در سابقه ثبت شد';delete form.dataset.requestId;if(form.elements.password)form.elements.password.value='';await reload();
   }catch(error){status.textContent=error.message;}finally{delete form.dataset.pending;button.disabled=false;}
  });
 };
})();
